export const OPEN_ROM_REVISION = "ad178dbe4d48cd6a317737a8e0e7e662f7e33d32";
export function readBundledOpenRoms() {
  const output = {};
  for (const [key, source] of Object.entries(SOURCES)) {
    const binary = atob(source.base64);
    if (binary.length !== source.expected) throw new Error("Invalid bundled Open ROM: " + key);
    const bytes = new Uint8Array(binary.length);
    for(let i=0;i<bytes.length;i++) bytes[i]=binary.charCodeAt(i);
    output[key]=bytes;
  }
  return output;
}
